function renderLocal(){const root=$("local-models");const count=$("text-library-count");if(!localModels.length){root.innerHTML='<div class="empty-state">Geen lokale GGUF-bestanden gevonden. Download modellen via de Modelwinkel.</div>';if(count)count.textContent="0 tekstmodellen";return;}const activeName=$("text-active-model")?.textContent||"";root.innerHTML='<div class="asset-group"><div class="asset-group-title"><b>GGUF · llama.cpp</b><span>'+localModels.length+' modellen</span></div>'+localModels.map((m,i)=>{const active=activeName===m.name;return '<div class="asset-row text-model-row" data-search="'+esc((m.name+' '+m.path+' '+(m.meta?.architecture||'')).toLowerCase())+'"><div class="asset-file text-model-file"><strong>'+esc(m.name)+'</strong><small>'+fmtBytes(m.size)+' · '+esc(m.meta?.architecture||"GGUF")+(m.meta?.layers?" · "+m.meta.layers+" lagen":"")+(m.meta?.parameters?" · "+Number(m.meta.parameters).toLocaleString("nl-NL")+" parameters":"")+(m.meta?.context?" · max ctx "+Number(m.meta.context).toLocaleString("nl-NL"):"")+'</small><small class="text-model-plan">'+(m.loadability?.loadable===false?'Niet laadbaar · '+esc(m.loadability.reason)+' · ':active?'Actief geladen · ':'')+(m.plan.fit==="likely"?"Past waarschijnlijk":m.plan.fit==="tight"?"CPU/GPU-mix":"Waarschijnlijk te groot")+' · Context '+$("load-context").value+' · totaal '+fmt(m.plan.required)+' · KV-cache '+fmt(m.plan.kvBytes)+'</small>'+(m.mmprojCandidates?.length?'<label class="mmproj-row">Visionprojector<select data-mmproj="'+i+'"><option value="">Automatisch</option><option value="none">Geen mmproj</option>'+m.mmprojCandidates.map(x=>'<option value="'+esc(x.path)+'">'+esc(x.name)+'</option>').join("")+'</select></label>':'')+'</div><div class="asset-actions"><button class="text-button" data-delete-local="'+i+'">Verwijderen</button><button class="primary-button" data-load-local="'+i+'" '+(active||m.loadability?.loadable===false?'disabled':'')+'>Laden</button></div></div>';}).join("")+'</div>';const q=$("text-model-search").value.trim().toLowerCase();if(q)root.querySelectorAll(".text-model-row").forEach(row=>row.hidden=!row.dataset.search.includes(q));if(count)count.textContent=(q?root.querySelectorAll('.text-model-row:not([hidden])').length+" van ":"")+localModels.length+" tekstmodellen";root.querySelectorAll("[data-load-local]").forEach(b=>b.addEventListener("click",()=>{const i=Number(b.dataset.loadLocal),sel=root.querySelector('[data-mmproj="'+i+'"]');loadTextModel(localModels[i],sel?sel.value:undefined);}));root.querySelectorAll("[data-delete-local]").forEach(b=>b.addEventListener("click",async()=>{const m=localModels[Number(b.dataset.deleteLocal)];if(!confirm("Verwijder "+m.name+" definitief van de schijf?"))return;try{await post("/api/models/delete",{path:m.path});toast("Model verwijderd");loadModels();}catch(e){toast(e.message);}}));}
async function loadModels(){try{const d=await api("/api/models?context="+encodeURIComponent($("load-context").value||4096)+"&cacheK="+encodeURIComponent($("load-k").value||"q8_0"));localModels=d.local||[];renderLocal();const s=$("chat-model"),old=s.value;s.innerHTML='<option value="">Selecteer model</option>';localModels.filter(m=>m.loadability?.loadable!==false).forEach(m=>{const o=document.createElement("option");o.value=m.path;o.textContent=m.name;s.append(o);});if([...s.options].some(o=>o.value===old))s.value=old;const quick=$("chat-load-model-select"),quickOld=quick.value;quick.innerHTML='<option value="">Selecteer lokaal GGUF-model</option>';localModels.filter(m=>m.loadability?.loadable!==false).forEach(m=>{const o=document.createElement("option");o.value=m.path;o.textContent=m.name+" · "+fmtBytes(m.size);quick.append(o);});if([...quick.options].some(o=>o.value===quickOld))quick.value=quickOld;await loadRuntime();}catch(e){$("local-models").innerHTML='<div class="empty-state">Modelbibliotheek: '+esc(e.message)+'</div>';}}
async function loadTextModel(m,mmproj){if(m.loadability?.loadable===false)return toast(m.loadability.reason);try{toast("Tekstmodel wordt geladen…");const r=await post("/api/runtime/text/load",{model:m.path,mmproj,context:Number($("load-context").value),gpuLayers:$("load-gpu").value,cacheK:$("load-k").value,cacheV:$("load-v").value});toast("Model gestart · PID "+r.pid+(r.cacheFallback?.length?" · cache automatisch aangepast naar F16":""));await loadRuntime();refresh();}catch(e){toast("Laden mislukt: "+e.message);await loadRuntime();}}
$("chat-load-model-select").addEventListener("change",()=>{const m=localModels.find(x=>x.path===$("chat-load-model-select").value);const wrap=$("chat-mmproj-wrap"),sel=$("chat-load-mmproj");wrap.hidden=!(m?.mmprojCandidates?.length);sel.innerHTML='<option value="">Automatisch</option><option value="none">Geen mmproj</option>'+(m?.mmprojCandidates||[]).map(x=>'<option value="'+esc(x.path)+'">'+esc(x.name)+'</option>').join("");});
$("chat-load-model-button").addEventListener("click",()=>{const m=localModels.find(x=>x.path===$("chat-load-model-select").value);if(!m)return toast("Selecteer eerst een tekstmodel");if(m.loadability?.loadable===false)return toast(m.loadability.reason);$("chat-model").value=m.path;loadTextModel(m,$("chat-load-mmproj").value||undefined);$("chat-load-summary").textContent="Model laden · "+m.name;$("chat-model-loader").open=false;});
const chatModelLoader=$("chat-model-loader");document.addEventListener("pointerdown",e=>{if(chatModelLoader.open&&!chatModelLoader.contains(e.target))chatModelLoader.open=false;});document.addEventListener("keydown",e=>{if(e.key==="Escape"&&chatModelLoader.open)chatModelLoader.open=false;});
