async function loadNativeVideoCatalog(){try{const d=await api("/api/video/native/catalog"),items=d.items||[];$("native-video-catalog").innerHTML=items.map(x=>'<article class="video-catalog-item"><div><b>'+esc(x.name)+'</b><small>'+esc(x.mode)+' · '+esc(x.license)+' · '+fmtBytes(x.total)+' totaal · '+(x.memoryVerdict==="too_big"?"past niet in GPU-geheugen":x.memoryVerdict==="tight"?"krappe GPU-geheugenmarge":"GPU-geheugenindicatie goed")+'</small></div><button class="secondary-button native-video-install" data-profile="'+esc(x.id)+'" type="button" '+(x.memoryVerdict==="too_big"?"disabled":"")+'>'+(x.memoryVerdict==="too_big"?"Niet passend":"Download model")+'</button></article>').join("");}catch(e){$("native-video-catalog").innerHTML='<div class="empty-state">Catalogus niet bereikbaar: '+esc(e.message)+'</div>';}}
$("native-video-catalog").addEventListener("click",async e=>{const b=e.target.closest(".native-video-install");if(!b)return;b.disabled=true;b.textContent="Toevoegen…";try{const d=await post("/api/video/native/catalog/install",{profile:b.dataset.profile});b.textContent="In wachtrij";toast((d.items?.length||0)+" modelbestanden toegevoegd aan de downloadwachtrij");await loadQueue();}catch(err){b.disabled=false;b.textContent="Download model";toast(err.message);}});
async function loadNativeVideoModels(){try{const d=await api("/api/video/native/models"),items=d.items||[];$("native-video-model-count").textContent=items.length+" modellen";$("native-video-model-inventory").innerHTML=items.length?items.map(x=>'<article class="asset-row"><div class="asset-icon">▶</div><div class="asset-info"><b>'+esc(x.name)+'</b><small>'+esc(x.category)+' · '+fmtBytes(x.size)+' · '+new Date(x.modified).toLocaleString("nl-NL")+'</small></div><button class="text-button native-video-delete" data-category="'+esc(x.category)+'" data-name="'+esc(x.name)+'" type="button">Verwijderen</button></article>').join(""):'<div class="empty-state">Nog geen eigen videomodellen geïnstalleerd. De bibliotheek is klaar voor diffusion-modellen, encoders, VAE’s, LoRA’s en interpolatiemodellen.</div>';}catch(e){$("native-video-model-inventory").innerHTML='<div class="empty-state">Videobibliotheek niet beschikbaar: '+esc(e.message)+'</div>';}}
$("refresh-native-video-models").addEventListener("click",()=>{loadNativeVideoModels();loadNativeVideoEngine();loadNativeVideoCatalog();});
$("native-video-model-inventory").addEventListener("click",async e=>{const b=e.target.closest(".native-video-delete");if(!b)return;if(!confirm("Videomodel "+b.dataset.name+" verwijderen?"))return;try{await fetch("/api/video/native/models",{method:"DELETE",headers:{"Content-Type":"application/json"},body:JSON.stringify({category:b.dataset.category,name:b.dataset.name})}).then(async r=>{const d=await r.json();if(!r.ok)throw Error(d.error||"Verwijderen mislukt");});await loadNativeVideoModels();await loadNativeVideoEngine();toast("Videomodel verwijderd");}catch(err){toast(err.message);}});
$("native-video-model-file").addEventListener("change",async e=>{const f=e.target.files?.[0];if(!f)return;if(f.size>80*1024**3){toast("Modelbestand groter dan 80 GiB");e.target.value="";return;}const status=$("native-video-upload-status");status.textContent="Uploaden: "+f.name;try{const folder=$("native-video-model-folder").value;const result=await new Promise((resolve,reject)=>{const x=new XMLHttpRequest();x.open("POST","/api/video/native/models/upload?folder="+encodeURIComponent(folder));x.setRequestHeader("X-File-Name",encodeURIComponent(f.name));x.upload.onprogress=v=>{if(v.lengthComputable)status.textContent="Uploaden: "+Math.round(v.loaded/v.total*100)+"%";};x.onload=()=>{let d={};try{d=JSON.parse(x.responseText);}catch{}if(x.status>=200&&x.status<300)resolve(d);else reject(Error(d.error||"Upload HTTP "+x.status));};x.onerror=()=>reject(Error("Uploadverbinding verbroken"));x.send(f);});status.textContent="Geïnstalleerd: "+result.name+" · "+fmtBytes(result.size);await loadNativeVideoModels();await loadNativeVideoEngine();toast("Videomodel toegevoegd aan eigen bibliotheek");}catch(err){status.textContent="Upload mislukt: "+err.message;toast(err.message);}finally{e.target.value="";}});
let videoMode="text",nativeVideoProfiles=[],nativeVideoRuntimeReady=false,videoSourceData=null,videoJobId=null,videoPollTimer=null;
function updateVideoMode(){const image=videoMode==="image";$("video-source-wrap").hidden=!image;$("video-mode-title").textContent=image?"Animeer je afbeelding":"Beschrijf je video";$("video-mode-description").textContent=image?"Gebruik een afbeelding als eerste frame en beschrijf de beweging":"Genereer een nieuwe video vanuit een tekstbeschrijving";document.querySelectorAll("[data-video-mode]").forEach(b=>b.classList.toggle("active",b.dataset.videoMode===videoMode));$("video-generate").textContent=image?"▧ Afbeelding animeren":"▶ Video genereren";}
document.querySelectorAll("[data-video-mode]").forEach(b=>b.addEventListener("click",()=>{videoMode=b.dataset.videoMode;updateVideoMode();}));
async function loadVideoStatus(){await loadNativeVideoEngine();}
async function loadVideoLibrary(){try{const d=await api("/api/videos"),items=d.items||[];$("video-library").innerHTML=items.length?items.map(x=>'<article class="video-library-item"><video src="'+esc(x.url)+'" muted preload="metadata" controls></video><div><b>'+esc(x.name)+'</b><small>'+fmtBytes(x.size)+' · '+new Date(x.modified).toLocaleString("nl-NL")+'</small><a href="'+esc(x.url)+'" download="'+esc(x.name)+'">Video downloaden ↓</a></div></article>').join(""):'<div class="empty-state">Nog geen opgeslagen video’s.</div>';}catch(e){$("video-library").innerHTML='<div class="empty-state">Videobibliotheek niet beschikbaar: '+esc(e.message)+'</div>';}}
$("video-source").addEventListener("change",async e=>{const f=e.target.files?.[0];videoSourceData=null;$("video-source-preview-wrap").hidden=true;if(!f)return;if(!/^image\/(png|jpeg|webp)$/.test(f.type)||f.size>16*1024*1024){toast("Kies een PNG-, JPEG- of WebP-afbeelding van maximaal 16 MB");e.target.value="";return;}try{videoSourceData=await readData(f);$("video-source-preview").src=videoSourceData;$("video-source-name").textContent=f.name+" · "+fmtBytes(f.size);$("video-source-preview-wrap").hidden=false;}catch(err){toast(err.message);}});
$("video-source-remove").addEventListener("click",()=>{videoSourceData=null;$("video-source").value="";$("video-source-preview-wrap").hidden=true;});
function showVideoResult(job){if(job.state==="completed"&&job.videos?.length){$("video-result").innerHTML=job.videos.map(v=>"<video class=\"video-player\" controls autoplay muted playsinline src=\""+esc(v.url)+"\"></video><a class=\"primary-button video-download\" href=\""+esc(v.url)+"\" download=\""+esc(v.name)+"\">Video downloaden</a>").join("");$("video-progress").value=100;$("video-status").textContent="Video voltooid en opgeslagen in je videobibliotheek.";}else if(job.state==="error"){$("video-status").textContent="Generatie mislukt: "+(job.error||"Onbekende fout");$("video-progress").hidden=true;}else if(job.state==="cancelled"){$("video-status").textContent="Video-generatie gestopt.";$("video-progress").hidden=true;}else{$("video-status").textContent=job.state==="running"?"Video wordt gegenereerd op de native Vulkan-GPU · segment "+(job.progress?.segment||job.segment||1)+"/"+(job.progress?.totalSegments||job.segmentCount||1)+"…":"Video staat in de native GPU-wachtrij…";$("video-progress").hidden=false;}}
async function prepareNativeVideoImage(data,width,height){return await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>{const canvas=document.createElement("canvas");canvas.width=width;canvas.height=height;const ctx=canvas.getContext("2d");const scale=Math.max(width/img.width,height/img.height),w=img.width*scale,h=img.height*scale;ctx.drawImage(img,(width-w)/2,(height-h)/2,w,h);resolve(canvas.toDataURL("image/jpeg",.92));};img.onerror=()=>reject(Error("Startafbeelding kon niet worden voorbereid"));img.src=data;});}
async function pollVideoJob(){if(!videoJobId)return;try{const d=await api("/api/video/jobs/"+encodeURIComponent(videoJobId)),job=d.job;showVideoResult(job);if(job.progress?.total_steps)$("video-progress").value=Math.round(100*(job.progress.step||0)/job.progress.total_steps);if(["completed","error","cancelled"].includes(job.state)){clearInterval(videoPollTimer);videoPollTimer=null;videoJobId=null;$("video-generate").disabled=!nativeVideoRuntimeReady;$("video-cancel").hidden=true;if(job.state==="completed")await loadVideoLibrary();}}catch(e){$("video-status").textContent="Status ophalen mislukt: "+e.message;}}
$("video-generate").addEventListener("click",async()=>{if(!nativeVideoRuntimeReady)return toast("Laad eerst een passend videomodel in de native Vulkan-engine");if(videoMode==="image"&&!videoSourceData)return toast("Kies eerst een startafbeelding");const prompt=$("video-prompt").value.trim();if(!prompt)return toast("Vul eerst een videoprompt in");const [w,h]=$("video-resolution").value.split("x").map(Number),fps=Number($("video-fps").value)||12,duration=Math.max(1,Math.min(60,Number($("video-duration").value)||4));let frames=Math.max(9,Math.min(289,Math.round(duration*fps)));frames=Math.max(5,Math.min(81,Math.round((frames-1)/4)*4+1));$("video-generate").disabled=true;$("video-cancel").hidden=false;$("video-progress").hidden=false;$("video-progress").removeAttribute("value");$("video-status").textContent="Native Vulkan-videogeneratie voorbereiden…";$("video-result").innerHTML="<div class=\"empty-state\">Video wordt voorbereid…</div>";try{const payload={mode:videoMode,duration,prompt,negative:$("video-negative").value,image:videoMode==="image"?await prepareNativeVideoImage(videoSourceData,w,h):null,width:w,height:h,fps,frames,steps:Number($("video-steps").value)||20,cfg:Number($("video-cfg").value)||6,flowShift:Number($("video-flow-shift").value)||3,seed:Number($("video-seed").value)};const d=await post("/api/video/native/generate",payload);videoJobId=d.job.id;await pollVideoJob();if(videoJobId)videoPollTimer=setInterval(pollVideoJob,2500);}catch(e){$("video-status").textContent="Starten mislukt: "+e.message;$("video-progress").hidden=true;$("video-cancel").hidden=true;$("video-generate").disabled=!nativeVideoRuntimeReady;toast(e.message);}});
$("video-cancel").addEventListener("click",async()=>{try{await post("/api/video/cancel",{});if(videoPollTimer)clearInterval(videoPollTimer);videoPollTimer=null;videoJobId=null;$("video-cancel").hidden=true;$("video-generate").disabled=!nativeVideoRuntimeReady;$("video-status").textContent="Stopverzoek verzonden naar de native GPU-engine.";$("video-progress").hidden=true;}catch(e){toast(e.message);}});
$("video-refresh").addEventListener("click",()=>{loadNativeVideoEngine();loadNativeVideoModels();loadVideoLibrary();});
updateVideoMode();